def check_circulant_3():
    n = 25
    # Try all combinations of S = {a, b, c}
    # This will be a 6-regular graph, but we want degree 3-5.
    # So we can remove some edges.
    # Let's try S = {a, b, c} and then remove edges to get degree 3-5.
    # Actually, let's just try S = {a, b, c} and check if it's 6-regular.
    # If it's 6-regular, we can remove edges to make it 3-5 regular.
    # But that's not easy.

    # Let's try S = {a, b} and see if we can add a few more edges.
    # Or just try S = {a, b, c} and check girth.
    for a in range(1, n // 2 + 1):
        for b in range(a + 1, n // 2 + 1):
            for c in range(b + 1, n // 2 + 1):
                edges = []
                for i in range(n):
                    edges.append((i, (i + a) % n))
                    edges.append((i, (i + b) % n))
                    edges.append((i, (i + c) % n))

                unique_edges = set()
                for u, v in edges:
                    unique_edges.add((min(u, v), max(u, v)))

                if get_girth(n, list(unique_edges)) >= 7:
                    # Check degrees
                    degrees = [0] * n
                    for u, v in unique_edges:
                        degrees[u] += 1
                        degrees[v] += 1
                    if all(3 <= d <= 5 for d in degrees):
                        return list(unique_edges)
    return None

